// #20 Generated files are marked and grouped.
//
// A tracked file is generated when its name contains `.generated.`, or when its first five lines carry a
// generated marker (see generated.mjs: "generated by", the at-sign generated tag, "do not edit"; any case).
// Predicate: every generated file
//   - is named `*.generated.*` or is listed in the manifest (scripts/generate/README.md, a file row or a
//     directory row above it), the fixed-path exceptions whose names consumers depend on;
//   - when commentable (not JSON, not binary), carries `Generated by <generator path>; do not edit.` in its
//     first three lines, naming a tracked file.
// Exemption `data-roots`: expected findings under `fixtures/` and `packs/<id>/upstream/` follow the fixtures
// convention (generator beside its output, #6) and are not scanned for markers.
// Exemption `tool-owned`: lockfiles (`*.lock`, `package-lock.json`) and `.changeset/README.md` are written
// by their tools, which mark them; they have no generator in this repository.
// The manifest itself and this gate's own sources and tests (which spell out the marker) are not scanned.

import { finding, sortFindings } from "../lib.mjs";
import { hasGeneratedMarker, headerGenerator, isCommentable, isGeneratedName, manifestRows, rowFor } from "../generated.mjs";

export const id = 20;
export const title = "Generated files are marked and grouped";
export const target = "100%";

export function check(repo) {
  const rows = manifestRows(repo);
  const findings = [];
  let generated = 0;
  for (const path of repo.files) {
    const named = isGeneratedName(path);
    if (!named && !hasGeneratedMarker(repo, path)) continue;
    generated += 1;
    if (!named && rowFor(rows, path) === undefined) {
      findings.push(finding(path, "generated (header marker) but neither named *.generated.* nor listed in scripts/generate/README.md"));
    }
    if (!isCommentable(repo, path)) continue;
    const generator = headerGenerator(repo, path);
    if (generator === null) {
      findings.push(finding(path, "missing `Generated by <generator path>; do not edit.` in its first three lines"));
    } else if (!repo.has(generator)) {
      findings.push(finding(path, `header names ${generator}, which is not a tracked file`));
    }
  }
  const failing = new Set(findings.map((item) => item.path)).size;
  const passing = generated - failing;
  const percent = generated === 0 ? 100 : Math.floor((passing * 100) / generated);
  return { actual: `${percent}% (${passing}/${generated})`, findings: sortFindings(findings) };
}
